(* Auto-start standby pump when level drops *)
VAR
    level : REAL;
END_VAR

level := Read('WaterPlant.Distribution.ClearWellLevel_m');
IF level < 2.0 THEN
    Write('WaterPlant.Distribution.DistPump3_Running', TRUE);
ELSIF level > 4.0 THEN
    Write('WaterPlant.Distribution.DistPump3_Running', FALSE);
END_IF;
